763→<!-- Redirect links and searches when in dual view mode -->
764→<script>
765→document.addEventListener("DOMContentLoaded", function () {
766→  if (!window.location.pathname.startsWith("/dual")) return;
767→
768→  function getTargetPanel() {
769→    const selected = document.querySelector('input[name="targetPanel"]:checked');
770→    return selected ? selected.value : "left";
771→  }
772→
773→  function loadInPanel(panel, path) {
774→    if (!path) return;
775→    const iframe = document.getElementById(`iframe-${panel}`);
776→    if (!iframe) return;
777→    const url = path.includes("?") ? path + "&embed=1" : path + "?embed=1";
778→    iframe.src = url;
779→    const inputBox = document.querySelector(`#panel-${panel} input`);
780→    if (inputBox) inputBox.value = path;
781→    console.log(`Loaded "${url}" into panel "${panel}"`);
782→  }
783→  
784→  document.querySelectorAll(".dual-aware a[href^='/'], a.dual-aware[href^='/']").forEach(link => {
785→    link.addEventListener("click", function (e) {
786→      e.preventDefault();
787→      const path = this.getAttribute("href");
788→      loadInPanel(getTargetPanel(), path);
789→    });
790→  });
791→
792→  const idForm = document.getElementById("idsearchForm");
793→  if (idForm) {
794→    idForm.addEventListener("submit", function (e) {
795→      e.preventDefault();
796→      const input = idForm.querySelector(".idsearchTerm").value.trim();
797→      if (!input) return;
798→
799→      let path = null;
800→
801→      if (/^\d+$/.test(input)) {
802→        path = "/go_to/" + encodeURIComponent(input);
803→      } else if (/^((\d+|end)(-(\d+|end))?\s*)+(open|solved|yes|no)?$/i.test(input)) {
804→        const parts = input.split(/\s+/).filter(Boolean);
805→        path = "/range/" + parts.map(encodeURIComponent).join("/");
806→      } else {
807→        alert("Invalid input format.");
808→        return;
809→      }
810→
811→      loadInPanel(getTargetPanel(), path);
812→    });
813→  }
814→
815→  const searchForm = document.getElementById("searchForm");
816→  if (searchForm) {
817→    searchForm.addEventListener("submit", function (e) {
818→      e.preventDefault();
819→      const input = searchForm.querySelector(".searchTerm").value.trim();
820→      if (!input) return;
821→
822→      const path = "/search/" + encodeURIComponent(input);
823→      loadInPanel(getTargetPanel(), path);
824→    });
825→  }
826→});
827→</script>
